<script>
const registrationForm=document.querySelector('[data-registration-wizard]');
if(registrationForm){
const steps=[...registrationForm.querySelectorAll('[data-registration-step]')],progress=[...document.querySelectorAll('[data-progress-step]')];
const previous=registrationForm.querySelector('[data-registration-previous]'),next=registrationForm.querySelector('[data-registration-next]'),submit=registrationForm.querySelector('[data-registration-submit]');
let current=0;registrationForm.noValidate=true;
function showStep(index){current=index;steps.forEach((step,i)=>step.hidden=i!==index);progress.forEach((item,i)=>{item.classList.toggle('is-complete',i<index);if(i===index)item.setAttribute('aria-current','step');else item.removeAttribute('aria-current');});previous.hidden=index===0;next.hidden=index===steps.length-1;submit.hidden=index!==steps.length-1;registrationForm.querySelector('[data-registration-caption]').textContent=`Step ${index+1} of ${steps.length}`;}
function checkStep(index){const invalid=[...steps[index].querySelectorAll('input,select')].find(field=>!field.checkValidity());if(invalid){showStep(index);invalid.reportValidity();return false;}return true;}
next.addEventListener('click',()=>{if(checkStep(current)){showStep(current+1);steps[current].querySelector('input,select')?.focus();}});previous.addEventListener('click',()=>showStep(current-1));
registrationForm.addEventListener('submit',event=>{if(current<steps.length-1){event.preventDefault();if(checkStep(current))showStep(current+1);return;}for(let i=0;i<steps.length;i++){if(!checkStep(i)){event.preventDefault();return;}}submit.disabled=true;submit.textContent='Registering...';});
const errorIndex=steps.findIndex(step=>step.querySelector('[aria-invalid=true]'));showStep(errorIndex>=0?errorIndex:0);
}
</script></body></html>
